const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    // Approximate bounding box for East Midlands, northeast England, and eastern Scotland.
    // This covers a significant portion of the specified regions.
    const geometry = ee.Geometry.Polygon(
      [
        [-5.0, 54.0], // West, South
        [-5.0, 59.0], // West, North
        [3.0, 59.0],  // East, North
        [3.0, 54.0]   // East, South
      ]
    );

    // Current period (Oct 1, 2023 - Jan 4, 2024)
    const currentStartDate = '2023-10-01';
    const currentEndDate = '2024-01-04';

    // Average period (1991-2020)
    const historicalStartYear = 1991;
    const historicalEndYear = 2020;

    // 2. Data Acquisition & Check
    const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY');

    // Get current period rainfall
    let currentCollection = chirps.filterDate(currentStartDate, currentEndDate).filterBounds(geometry);
    const currentSize = await currentCollection.size().getInfo();

    if (currentSize === 0) {
      console.log("No CHIRPS data found for the current period.");
      console.log("C1");
      return;
    }
    console.log(`Current Period Images: ${currentSize}`);

    // Calculate total rainfall for the current period
    const currentTotalPrecipitation = await currentCollection.select('precipitation')
      .sum()
      .reduceRegion({
        reducer: ee.Reducer.mean(), // Mean precipitation over the region
        geometry: geometry,
        scale: 5000, // CHIRPS resolution is ~5km, use 5km scale.
        maxPixels: 1e9
      })
      .get('precipitation')
      .getInfo();

    if (currentTotalPrecipitation === null || isNaN(currentTotalPrecipitation)) {
      console.log("Calculation of current total precipitation failed.");
      console.log("C3");
      return;
    }
    console.log(`Current Total Precipitation (mm): ${currentTotalPrecipitation.toFixed(2)}`);

    // Calculate average historical rainfall for the same months over 1991-2020
    let historicalAnnualTotals = ee.List([]);

    for (let year = historicalStartYear; year <= historicalEndYear; year++) {
      const histPeriodStartDate = ee.Date.fromYMD(year, 10, 1); // Oct 1st
      const histPeriodEndDate = ee.Date.fromYMD(year + 1, 1, 4); // Jan 4th of next year

      const histCollection = chirps.filterDate(histPeriodStartDate, histPeriodEndDate).filterBounds(geometry);
      const histSize = await histCollection.size().getInfo();

      if (histSize === 0) {
        console.log(`Warning: No CHIRPS data for historical year ${year}. Skipping.`);
        continue;
      }

      const yearTotalPrecipitation = histCollection.select('precipitation')
        .sum()
        .reduceRegion({
          reducer: ee.Reducer.mean(),
          geometry: geometry,
          scale: 5000,
          maxPixels: 1e9
        })
        .get('precipitation');

      historicalAnnualTotals = historicalAnnualTotals.add(yearTotalPrecipitation);
    }

    const validHistoricalTotals = await historicalAnnualTotals.filter(ee.Filter.neq('item', null)).getInfo();
    if (validHistoricalTotals.length === 0) {
      console.log("No valid historical data points for the average calculation.");
      console.log("C1"); // No historical data to compare against
      return;
    }

    const historicalAveragePrecipitation = ee.List(validHistoricalTotals)
      .reduce(ee.Reducer.mean())
      .getInfo();

    if (historicalAveragePrecipitation === null || isNaN(historicalAveragePrecipitation)) {
      console.log("Calculation of historical average precipitation failed.");
      console.log("C3");
      return;
    }

    console.log(`Historical Average Precipitation (mm, 1991-2020): ${historicalAveragePrecipitation.toFixed(2)}`);

    // 5. Validation & Final Answer
    if (currentTotalPrecipitation > historicalAveragePrecipitation) {
      console.log("A");
    } else {
      console.log("B");
    }

  } catch (error) {
    console.log(`An error occurred: ${error.message}`);
    console.log("D");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
